<template><section class="apps-manager"><header><h2>Apps</h2><p>uDOS keeps your local collection. Your chosen apps manage their account and cloud sync; Snackbar coordinates local connections.</p></header><section v-if="platform==='macos'"><h3>Local Mac apps</h3><p>Add Google and Apple accounts in macOS Internet Accounts, then choose the local app lists here. iCloud settings remain in macOS.</p><ConnectionsPanel connections-only provider-mode="local" /></section><section v-else><h3>Local Linux and desktop pathway</h3><p>Use Evolution with GNOME Online Accounts, or Thunderbird, to manage account sync. Live Evolution/Thunderbird adapters are not implemented yet; browser HTML exchange below is available now.</p></section><SnackbarSyncPanel /><section class="apps-browser"><h3>Bookmarks and reading lists</h3><p>Import bookmark HTML from Safari, Chrome, Firefox or Edge. Safari exports can include Reading List. This is manual file exchange; your browser owns continuous cloud sync.</p><div class="app-actions"><label for="browser-source">Browser</label><select id="browser-source" v-model="browser"><option value="safari">Safari</option><option value="chrome">Chrome</option><option value="firefox">Firefox</option><option value="edge">Edge</option><option value="browser">Other</option></select><label class="usx-btn" for="browser-export-file"><UIcon name="upload_file" />Import HTML</label><input id="browser-export-file" type="file" accept=".html,.htm,text/html" :disabled="busy" @change="importFile" /><button class="usx-btn" :disabled="busy" @click="exportFile"><UIcon name="download" />Export HTML</button></div><p v-if="message" role="status">{{ message }}</p><p v-if="error" role="alert">{{ error }}</p><div class="app-actions"><button v-for="kind in ['bookmarks','reading_list']" :key="kind" class="usx-btn" :aria-pressed="activeKind===kind" @click="activeKind=kind">{{ kind==='bookmarks'?'Bookmarks / favourites':'Reading list' }} · {{ records.filter(r=>r.kind===kind).length }}</button></div><article v-for="record in records.filter(r=>r.kind===activeKind)" :key="record.id" class="browser-link"><a :href="record.data.url" target="_blank" rel="noopener noreferrer">{{ record.data.title }}</a><small>{{ record.data.folders?.join(' / ') }}</small><label v-if="record.kind==='reading_list'"><input type="checkbox" :checked="record.data.read" @change="markRead(record,($event.target as HTMLInputElement).checked)" />Read locally</label></article></section><section><h3>Recommended apps</h3><p>Maintained for the integration modes shown. App-managed sync does not imply a live uDOS adapter.</p><article v-for="app in apps" :key="app.id" class="recommended-app"><div><h4>{{ app.name }}</h4><small>{{ app.points.join(' · ') }} · {{ app.mode.replaceAll('-',' ') }}</small><p>{{ app.description }}</p></div><a class="usx-btn" :href="app.url" target="_blank" rel="noopener noreferrer">Official site<UIcon name="open_in_new" /></a></article></section><details v-if="preferences.advancedView"><summary>Advanced direct cloud connections</summary><p>Optional direct APIs contact the cloud from uCore. They are separate from the local-app pathway.</p><ConnectionsPanel connections-only provider-mode="cloud" /></details></section></template>
<script setup lang="ts">
import { onMounted,ref } from 'vue';import { UCORE_BASE } from '../../api/base';import { useSettingsStore } from '../../stores/settings';import ConnectionsPanel from './ConnectionsPanel.vue';import SnackbarSyncPanel from '../../skills/molecules/SnackbarSyncPanel.vue';import UIcon from '../../skills/atoms/UIcon.vue';
const preferences=useSettingsStore(),platform=ref(''),apps=ref<any[]>([]),records=ref<any[]>([]),activeKind=ref('bookmarks'),browser=ref('safari'),busy=ref(false),error=ref(''),message=ref('');
async function request(path:string,body?:object){const response=await fetch(`${UCORE_BASE}${path}`,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});if(!response.ok)throw Error((await response.text()).slice(0,240));return response.json();}
async function loadRecords(){const result=await request('/api/connections/records');records.value=result.records.filter((r:any)=>['bookmarks','reading_list'].includes(r.kind));}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;busy.value=true;error.value='';try{if(file.size>2_000_000)throw Error('Choose an HTML export under 2 MB.');const result=await request('/api/snackbar/sync/browser/import',{html:await file.text(),source:browser.value});await loadRecords();message.value=`${result.imported} added · ${result.updated} updated. No browser settings were changed.`;}catch(e){error.value=e instanceof Error?e.message:'Import unavailable';}finally{busy.value=false;input.value='';}}
async function exportFile(){busy.value=true;try{const response=await fetch(`${UCORE_BASE}/api/snackbar/sync/browser/export`);if(!response.ok)throw Error('Export unavailable');const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download='udos-bookmarks.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=e instanceof Error?e.message:'Export unavailable';}finally{busy.value=false;}}
async function markRead(record:any,read:boolean){try{await request('/api/connections/records',{...record,data:{...record.data,read}});await loadRecords();}catch(e){error.value=e instanceof Error?e.message:'Could not save reading state';}}
onMounted(async()=>{try{const data=await request('/api/apps');platform.value=data.platform;apps.value=data.apps;if(platform.value!=='macos')browser.value='firefox';await loadRecords();}catch(e){error.value=e instanceof Error?e.message:'Apps unavailable';}});
</script>
<style scoped>.apps-manager{display:grid;gap:20px;text-align:left;padding:16px}.apps-manager h2,.apps-manager h3,.apps-manager h4{margin:0 0 8px}.apps-manager p{margin:0 0 12px;color:var(--usx-color-on-surface-muted);font-size:var(--usx-font-size-sm);line-height:1.5}.app-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:8px 0}.usx-btn{display:inline-flex;align-items:center;gap:6px;min-height:32px;padding:4px 8px;margin:0}.apps-manager select{height:32px;margin:0;padding:4px 8px;border:1px solid var(--usx-color-border);background:var(--usx-color-surface);color:inherit;border-radius:var(--usx-radius-sm);box-shadow:none}#browser-export-file{position:absolute;width:1px;height:1px;opacity:0}.recommended-app{display:flex;gap:12px;align-items:start;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--usx-color-border)}.recommended-app>div{flex:1}.recommended-app small,.browser-link small{font-size:var(--usx-font-size-sm);color:var(--usx-color-on-surface-muted)}.browser-link{display:grid;gap:4px;padding:8px 0;border-bottom:1px solid var(--usx-color-border)}.browser-link label{display:flex;align-items:center;gap:8px;margin:0;font-size:var(--usx-font-size-sm)}.browser-link input{margin:0}.apps-manager [role=alert]{color:var(--usx-color-danger)}summary{cursor:pointer}@media(max-width:36rem){.recommended-app{flex-direction:column}}</style>
